// priority: 1000
// Must load before every other startup script: several read global.item / blocks / fluid at
// top level, and same-priority scripts load in filesystem-walk order (differs per machine).
global.item = {};

// ############################## Assignments ##############################
var i = global.item;
i.na = 'minecraft:barrier';
i.none = 'createdeco:gray_decal';

// ############################## Meta / Custom Items ##############################

//Incomplete Recipe Placeholders
//  Per-recipe kubejs incomplete items are now registered in
//  startup_scripts/changes/transition_items.js and referenced with R.incomplete('<key>')
//  / a ['<key>'] transitionalItem arg - no dict entry needed.
i.incomplete = 'kubejs:incomplete_item';
i.i_vibration_mechanism = 'create_things_and_misc:incomplete_vibration_mechanism';
i.i_redstone_mechanism = 'vintageimprovements:incomplete_redstone_module';

//Immersive Engineering
i.blueprint = 'immersiveengineering:blueprint';

// ############################## Unsorted (Possible duplicates) ##############################

i.wirecoil_hv = 'immersiveengineering:wirecoil_steel';
	i.coil_hv = 'immersiveengineering:wirecoil_steel';
i.coil_block_hv = 'immersiveengineering:coil_hv';
i.culture_base = '#creativeengineering:culture_base';
i.amethyst_dust = 'creativeengineering:amethyst_dust';
i.amethyst_lens = 'creativeengineering:amethyst_lens';
i.wood_pellets = 'creativeengineering:wood_pellets';
i.layered_obsidian = 'creativeengineering:layered_obsidian';
// Oven — FD cooking-pot style baking block. Java: patcherMod oven/ package (block, GUI, JEI, the
// creativeengineering:baking recipe type) | recipes: kubejs/data/creative_delight/kubejs/creativeengineering/baking.js (NCH.ceBaking) |
// bakeware items: Creative Delight kubejs_startup/creativeengineering/bakeware.js | feature_writeup/oven.md
i.oven = 'creativeengineering:oven';
i.baking_sheet = 'creativeengineering:baking_sheet';
i.cake_pan = 'creativeengineering:cake_pan';
i.pie_tin = 'creativeengineering:pie_tin';
i.muffin_tin = 'creativeengineering:muffin_tin';
i.t_bakeware = '#creativeengineering:bakeware'; // the oven's tool-slot filter (OvenItemHandler.BAKEWARE)
i.t_bakeware_baking_sheet = '#creativeengineering:bakeware/baking_sheet';
i.t_bakeware_cake_pan = '#creativeengineering:bakeware/cake_pan';
i.t_bakeware_pie_tin = '#creativeengineering:bakeware/pie_tin';
i.t_bakeware_muffin_tin = '#creativeengineering:bakeware/muffin_tin';
i.catfish = 'alexsmobs:raw_catfish';
i.catfish_slice = 'alexsdelight:raw_catfish_slice';
i.felsic_scrap = 'creativeengineering:felsic_scrap';
i.component_diamond = 'creativeengineering:component_diamond';
// Air Brake — hold-to-use elytra brake. Item: startup_scripts/items/air_brake.js |
// deceleration physics: patcherMod gear/AirBrakeHandler.java | knobs: CEConfig.AirBrake
i.air_brake = 'creativeengineering:air_brake';
// Tier shields — copper..dragon (iron = minecraft:shield), vanilla's shield model with a texture
// per tier (kubejs/assets/creativeengineering/textures/entity/shield/). Java items:
// patcherMod shield/ package | every tunable (reduction per damage type, wear, effects,
// durability): CEConfig.SHIELDS = [shields] in config/creativeengineering-common.toml.
// ce_-prefixed on purpose: i.copper_shield (below) is everythingcopper's removed shield.
i.ce_copper_shield = 'creativeengineering:copper_shield';
i.ce_gold_shield = 'creativeengineering:gold_shield';
i.ce_diamond_shield = 'creativeengineering:diamond_shield';
i.ce_netherite_shield = 'creativeengineering:netherite_shield';
i.ce_echo_shield = 'creativeengineering:echo_shield';
i.ce_felsic_shield = 'creativeengineering:felsic_shield';
i.ce_dragon_shield = 'creativeengineering:dragon_shield';
// Potion buckets — area-of-effect lingering-potion items (i.potion_bucket is IE's).
// Items: startup_scripts/items/potion_buckets.js | effect: startup_scripts/func/potion_area.js
i.ce_potion_bucket = 'creativeengineering:potion_bucket';
i.ce_splash_potion_bucket = 'creativeengineering:splash_potion_bucket';
i.ce_lingering_potion_bucket = 'creativeengineering:lingering_potion_bucket';
// Camera bags - item inventory for Exposure gear (#exposure_extras:camera_equipment only).
// Java items: exposureBackport src/extras (mod exposure_extras) | slot counts: exposure_extras-common.toml
// [camera_bag] | recipes: server_scripts/equipment/camera_bag.js (smithing upgrades keep the contents)
i.leather_camera_bag = 'exposure_extras:leather_camera_bag';
i.iron_camera_bag = 'exposure_extras:iron_camera_bag';
i.netherite_camera_bag = 'exposure_extras:netherite_camera_bag';
