// ############################## Validation ##############################

StartupEvents.postInit(() => {
	let missing = [];
	for (let key in i) {
		let id = i[key];
		if (typeof id !== 'string') {
			// Object-shaped ingredient (e.g. NBT matchers) — skip tag/item validation
			continue;
		}
		if (id.startsWith('#')) {
			let tagItems = Ingredient.of(id).itemIds;
			if (!tagItems || tagItems.length === 0) {
				missing.push(key + ' -> ' + id + ' (tag not found or empty)');
			}
		} else {
			if (!Item.exists(id)) {
				missing.push(key + ' -> ' + id);
			}
		}
	}
	if (missing.length > 0) {
		console.warn('[item_dict] Missing/invalid item IDs:\n' + missing.join('\n'));
	}
});

